export default "<template>\n  <div class=\"case\">\n    <p class=\"case-title\">TreeGrid</p>\n    <ev-tree-grid\n      :columns=\"columns\"\n      :rows=\"tableData\"\n      :width=\"widthMV\"\n      :height=\"heightMV\"\n      :option=\"{\n        adjust: true,\n        useGridSetting: {\n          use: true,\n        },\n      }\"\n      @resize-column=\"onResizeColumn\"\n      @change-column-status=\"onChangeColumnStatus\"\n    >\n    </ev-tree-grid>\n    <div class=\"description column-event-description\">\n      <div class=\"form-rows\">\n        <div class=\"form-row\">\n          <span class=\"badge yellow\">\n            Resize Column Width\n          </span>\n          <ev-text-field\n            v-model=\"columnEventsInfo.resize\"\n            class=\"custom-text-area\"\n            type=\"textarea\"\n            readonly\n          />\n        </div>\n        <div class=\"form-row\">\n          <span class=\"badge yellow\">\n            Grid Column Setting(Column Show/Hide Status)\n          </span>\n          <ev-text-field\n            v-model=\"columnEventsInfo.status\"\n            class=\"custom-text-area\"\n            type=\"textarea\"\n            readonly\n          />\n        </div>\n      </div>\n    </div>\n\n  </div>\n</template>\n\n<script>\nimport { ref } from 'vue';\n\nexport default {\n  setup() {\n    const tableData = ref([]);\n    const widthMV = ref('100%');\n    const heightMV = ref(300);\n    const columnEventsInfo = ref({\n      resize: '',\n      order: '',\n      status: '',\n    });\n    const getData = () => {\n      tableData.value = [\n        {\n          id: 'Exem 0',\n          date: '2016-05-01',\n          name: '1111',\n          expand: true,\n        },\n        {\n          id: 'Exem 1',\n          date: '2016-05-01',\n          name: '2222',\n          value: 123,\n          expand: true,\n          children: [{\n            id: 'Exem 2',\n            date: '2016-05-02',\n            name: '2',\n            value: 222,\n            expand: false,\n            children: [{\n              id: 'Exem 3',\n              date: '2016-05-02',\n              name: '3',\n              value: 3333,\n              uncheckable: true,\n            }, {\n              id: 'Exem 4',\n              date: '2016-05-02',\n              name: '4',\n              expand: false,\n              uncheckable: true,\n              children: [{\n                id: 'Exem 5',\n                date: '2016-05-02',\n                name: '5',\n                children: [{\n                  id: 'Exem 51',\n                  date: '2016-05-02',\n                  name: '1251',\n                  children: [{\n                    id: 'Exem 52',\n                    date: '2016-05-02',\n                    name: '20000',\n                  }],\n                }],\n              }, {\n                id: 'Exem 6',\n                date: '2016-05-02',\n                name: '6',\n              }],\n            }],\n          }, {\n            id: 'Exem 7',\n            date: '2016-05-03',\n            name: '7',\n            children: [{\n              id: 'Exem 8',\n              date: '2016-05-03',\n              name: '8',\n              value: 333,\n            }, {\n              id: 'Exem 9',\n              date: '2016-05-03',\n              name: '9',\n            }, {\n              id: 'Exem 10',\n              date: '2016-05-03',\n              name: '10',\n            }],\n          }, {\n            id: 'Exem 11',\n            date: '2016-05-04',\n            name: '11',\n          }],\n        },\n      ];\n    };\n    const columns = ref([\n      { caption: 'ID', field: 'id', type: 'number' },\n      { caption: 'Date', field: 'date', type: 'string' },\n      {\n        caption: 'Name',\n        field: 'name',\n        type: 'float',\n        summaryType: 'sum',\n        summaryOnlyTopParent: true,\n        summaryRenderer: 'Sum: {0} 최상위 부모만 summary',\n        decimal: 1,\n      },\n      {\n        caption: 'Value',\n        field: 'value',\n        type: 'number',\n        summaryType: 'sum',\n        summaryRenderer: 'Sum: {0} 모든 row summary',\n        decimal: 1,\n      },\n    ]);\n\n    const onResizeColumn = (columnInfo) => {\n      columnEventsInfo.value.resize = JSON.stringify(columnInfo, null, 2);\n    };\n    const onChangeColumnStatus = (columnInfo) => {\n      columnEventsInfo.value.status = JSON.stringify(columnInfo, null, 2);\n    };\n\n    getData();\n\n    return {\n      columns,\n      tableData,\n      widthMV,\n      heightMV,\n      columnEventsInfo,\n      onResizeColumn,\n      onChangeColumnStatus,\n    };\n  },\n};\n</script>\n\n<style lang=\"scss\">\n.description {\n  .form-rows {\n    display: flex;\n    flex-direction: row;\n    gap: 10px;\n  }\n\n  .form-row {\n    width: 50%;\n  }\n\n  .badge {\n    margin-bottom: 2px;\n    margin-right: 5px !important;\n  }\n}\n\n.column-event-description {\n  min-width: 200px;\n  min-height: 300px;\n\n  .ev-textarea {\n    height: 200px !important;\n  }\n}\n</style>\n";